// scripts/cbm2-self-closeout.mjs
//
// CBM-2 self-validation closeout — the card's OWN bundle is generated by the
// PRODUCTION Graph closeout hook（runSubagentGraph → runColimaGraph →
// runMandatoryGraphCloseout → runCloseoutGate）, NOT by a hand-written source
// or a manual CLI invocation.
//
// The graph is the REAL review/repair ceremony:
//   SA-R1 ‖ SA-R2 -> SA-W1 -> SA-V1
//   SA-W1 lifecycle: writer (attempt 0) -> INDEPENDENT review agent finds an
//   evidence gap -> REPAIR (attempt 1) -> re-review PASS -> verifier.
// The mandatory closeout hook then auto-generates the CBM-2 bundle from the
// structured graph result + git-derived repo identity.
//
// Run: node scripts/cbm2-self-closeout.mjs

import { homedir } from "node:os";
import { mkdirSync, rmSync } from "node:fs";
import { join } from "node:path";
import { runSubagentGraph } from "../src/subagent/subagent-graph-runner.mjs";

const HOME = homedir();
const REPO_A = "/Volumes/NVM2T/Development/autoloop";
const SCRATCH = `${HOME}/autoloop-cbm2-self-closeout`;
const PROFILE = "autoloop-graph";
const PARENT = { scope: { allowed_paths: ["docs/"], forbidden_paths: [".git"] } };
const SCOPE = "docs/pi-graph-output";
const EXECUTION_ID = "cbm2-self-closeout-20260807";
const OUT = "/Users/zhengfengqing/Desktop/AutoLoop-Review/governance/review-bundle";

const roPhase = (phaseId, taskType) => ({
  phase_id: phaseId,
  depends_on: [],
  effects: { artifact_mutation: "none" },
  runtime: {
    mode: "subagent",
    agentRole: "readonly-analyst",
    taskType,
    objective: `read-only ${taskType} over /src/docs`,
    expect: { stdoutContains: [`SUBAGENT_DONE:${taskType}`] },
    limits: { memoryMiB: 256 },
    sleep: 3,
  },
});

const writerPhase = {
  phase_id: "SA-W1",
  depends_on: ["SA-R1", "SA-R2"],
  effects: { artifact_mutation: "required", boundaries: { artifact: [SCOPE] } },
  runtime: {
    mode: "subagent",
    agentRole: "writer",
    taskType: "write_report_with_gap",
    repairTaskType: "repair_report",
    objective: `writer write_report_with_gap over /work/${SCOPE} using dependency results`,
    expect: { stdoutContains: ["SUBAGENT_DONE:write_report_with_gap"] },
    limits: { memoryMiB: 256 },
  },
};

const verifierPhase = {
  phase_id: "SA-V1",
  depends_on: ["SA-W1"],
  effects: { artifact_mutation: "none" },
  runtime: {
    mode: "subagent",
    agentRole: "verifier",
    taskType: "verify_writer",
    objective: "verify writer SA-W1 diff/tests/scope + independent review from /results artifacts",
    expect: { stdoutContains: ["SUBAGENT_DONE:verify_writer"] },
    limits: { memoryMiB: 256 },
  },
};

const ir = { phases: [roPhase("SA-R1", "count_todos"), roPhase("SA-R2", "inventory_markdown"), writerPhase, verifierPhase] };

const closeout = {
  requiresReview: true,
  outDir: OUT,
  cardId: "AUTOLOOP-PI-GRAPH-CBM2-1",
  cardTitle: "Memory Contract and Schema Definition",
  cardType: "implementation",
  objective: "Define the formal AutoLoop Codebase Memory Contract v1: MemoryRecordV1 envelope, CODE/EXECUTION/DECISION record contracts, strict recursive canonical identity, trust promotion ladder, validity/stale/invalidated/tombstone/conflict semantics, scope baselines, lifecycle events, source/evidence contract, security allowlist/denylist, SQLite DDL + pinned-tokenizer FTS5, append-only JSONL journal with hash chain + SQLite rebuild, migration contract, and the full validation API. NO production Graph retrieval or write-back in this card.",
  authorizedScope: [
    "src/memory/",
    "test/memory/",
    "package.json",
  ],
  unauthorizedScope: [
    "Graph production retrieval node",
    "automatic write-back to long-term memory",
    "automatic memory query during task execution",
    "scheduler decision modification",
    "writer/reviewer prompt modification",
    "external DB / embedding API / vector DB / network",
    "storing secrets/credentials/env/private data",
    "self-evolution",
    "sub-agent spawning sub-agents",
    "multi-writer parallel",
    "commit/push/merge/seal",
  ],
  designDecisions: [
    "MemoryRecordV1 = autoloop.memory-record/v1; fixed envelope schema/recordId/recordType/identity/subject/content/source/scope/trust/validity/lifecycle/timestamps/evidence/security/metadata; unknown schema/type fails closed",
    "recordId = sha256(recursiveCanonical({schema, recordType, identity, subject, scope, sourceIdentity})); logicalKey = sha256(canonical({schema, recordType, identity, scope})); contentHash = sha256('content:'+canonical(content)); metadata/lifecycle/evidence/timestamps never change recordId",
    "strict canonical JSON: code-point key sort, array order preserved, undefined/NaN/Infinity/BigInt rejected, Date->RFC3339 UTC, raw strings; CBM-1 shallow-replacer collision codified as zero-tolerance",
    "trust ladder RAW->UNVERIFIED->VERIFIED->REVIEWED->CONFIRMED; writer/repair self-promotion always rejected; VERIFIED needs verifier evidence identity; REVIEWED needs independent review + empty blocking; CONFIRMED needs Controller ruling; skip-level needs explicit import contract; downgrades create DOWNGRADED lifecycle events",
    "validity CURRENT/STALE/INVALIDATED/TOMBSTONED/CONFLICTED; tree/commit/worktree/content baseline changes mark STALE; STALE never a trusted final answer; tombstone keeps identity+history; conflicts surfaced together (never silently merged)",
    "scope model: repository/worktree/commit/tree/path/symbol/content/graphRun/task/global; worktree = hard isolation boundary; tree-bound CODE carries validityTree; execution memory always graphRun-bound; decision memory may be global-scoped with authority",
    "lifecycle events append-only: CREATED/VALIDATED/PROMOTED/DOWNGRADED/MARKED_STALE/INVALIDATED/TOMBSTONED/SUPERSEDED/RESTORED/MIGRATED; history never overwritten",
    "evidence: manifestDigest + items(allowlisted regular files, no symlink, no escape, hash recomputed) + verifier/review/controller identities gated by trust",
    "SQLite primary (node:sqlite, zero deps): foreign_keys ON, WAL, synchronous NORMAL; tables memory_records/lifecycle_events/evidence/relationships/conflicts/migrations; FTS5 ADOPTED with PINNED tokenizer 'unicode61 remove_diacritics 0' (SQLite 3.53.2); normal (non-contentless) FTS table for deterministic rebuild",
    "JSONL journal: autoloop.memory-journal-event/v1; hash chain eventDigest = sha256(canonical({journalSequence,eventId,recordId,operation,payloadDigest,previousDigest})); fixed genesis; fsync per append; partial trailing line detected; corrupted middle line fail-closed; SQLite rebuild from journal verified identity-equal",
    "migration v1 with checksum; unknown FUTURE version fails closed (MIGRATION_INVALID)",
    "security: reuse scanForSecrets on RAW string fields (JSON escaping weakens quote-sensitive patterns); ingestion allowlist/denylist; hostile text stored as DATA only; no SQL injection (parameterized queries); secret rejected before journal append",
  ],
  negativeCases: [
    "unknown schema/recordType/trust/validity -> SCHEMA_INVALID",
    "fake recordId / tampered identity field -> IDENTITY_MISMATCH",
    "undefined/NaN/Infinity/BigInt -> CANONICALIZATION_FAILED",
    "shallow-replacer collision regression (CBM-1 defect)",
    "writer/repair self-promotion -> TRUST_TRANSITION_INVALID",
    "skipped trust level -> TRUST_TRANSITION_INVALID (unless import contract)",
    "stale/invalidated/tombstoned excluded from trusted retrieval",
    "conflicts surfaced together; never silently merged",
    "secret in record/content/journal -> SECRET_DETECTED (pre-write)",
    "evidence path escape/symlink -> PATH_NOT_ALLOWED",
    "corrupted middle journal line / duplicate sequence / gap -> JOURNAL_CHAIN_INVALID",
    "unknown future migration -> MIGRATION_INVALID",
    "hostile/SQL-injection text stored as data, never executed",
  ],
  regression: [
    { suite: "npm run check (syntax)", tests: 1, pass: 1, fail: 0 },
    { suite: "test:memory-contract (canonical/record/trust/validity/sqlite/jsonl/security)", tests: 81, pass: 81, fail: 0 },
    { suite: "test:governance", tests: 198, pass: 198, fail: 0 },
    { suite: "test:scripted-lifecycle", tests: 43, pass: 43, fail: 0 },
    { suite: "test:v2", tests: 357, pass: 357, fail: 0 },
    { suite: "test:c2", tests: 43, pass: 43, fail: 0 },
    { suite: "test:c3", tests: 41, pass: 41, fail: 0 },
    { suite: "test:colima-all (incl. graph-closeout e2e)", tests: 41, pass: 41, fail: 0 },
  ],
  regressionSummary: "At CBM-2 closeout time: check OK, memory-contract 81/81, governance 198/198, scripted-lifecycle 43/43, v2 357/357, c2 43/43, c3 41/41, colima-all 41/41 (one infra flake in the suite — first container after fresh VM creation — re-verified 6/6 standalone on the exact file; no code-related failure).",
  repairBudgetMaxAttempts: 1,
  executiveSummary: "CBM-2 complete: MemoryRecordV1 + CODE/EXECUTION/DECISION contracts, strict canonical identity with collision regressions, trust ladder with no self-promotion, validity/tombstone/conflict semantics, SQLite DDL + pinned FTS5, JSONL hash-chain journal with verified SQLite rebuild, migration contract, 81 focused tests. This bundle auto-generated by the production Graph closeout hook after the independent review agent PASS. NO production retrieval/write-back in this card.",
  recommendedNextStep: "CBM-3 Local Memory Store and Deterministic Retrieval Engine",
  rollbackProcedure: "Remove src/memory/ and test/memory/ and revert package.json test:memory-contract script; no production Graph path references the memory layer yet.",
  openQuestions: [],
  risks: ["retrieval digest determinism depends on canonical JSON + pinned FTS tokenizer; CBM-3 must not let FTS scoring enter the digest"],
  limitations: [
    "production Graph retrieval / write-back NOT connected (CBM-3/CBM-4 scope)",
    "no automatic memory query during task execution",
    "execution-memory retention windowing deferred (append-only for v1)",
  ],
};

mkdirSync(SCRATCH, { recursive: true });
mkdirSync(OUT, { recursive: true });

const r = await runSubagentGraph({
  ir,
  parent: PARENT,
  cwd: REPO_A,
  executionId: EXECUTION_ID,
  profile: PROFILE,
  repoPath: REPO_A,
  scratchRoot: SCRATCH,
  maxRepairAttempts: 1,
  timeoutMs: 240000,
  closeout,
});

console.log(`graph final=${r.final} reason=${r.reason ?? "null"}`);
console.log(`closeout applied=${r.closeout.applied} final=${r.closeout.final} holdCode=${r.closeout.holdCode ?? "null"}`);
if (r.closeout.reason) console.log(`closeout reason: ${r.closeout.reason}`);
if (r.closeout.bundlePath) {
  console.log(`bundle: ${r.closeout.bundlePath}`);
  console.log(`reviewBundleIdentity: ${r.closeout.bundle.identity}`);
  console.log(`reviewBundleSha256: ${r.closeout.bundle.sha256}`);
}
const w1 = r.nodeResults.find((n) => n.nodeId === "SA-W1");
if (w1) console.log(`W1 attempt=${w1.attempt} review=${w1.reviewResult?.recommendedAction} blocking=${JSON.stringify(w1.reviewResult?.blockingFindings ?? [])}`);

rmSync(SCRATCH, { recursive: true, force: true });
process.exit(r.final === "PASS" && r.closeout.final === "PASS" ? 0 : 1);
